\label{lemma:convolution-deterministic}
	Let $f\in L^1(\mathbb{T}^d)$ and $P\in C^k(\mathbb{T}^d)$ for some $k\in \mathbb{N}\cup\{\infty\}$. Then the convolution of $f$ and $P$
	\[
	(P*f)(\boldsymbol{z})=\int_{\mathbb{T}^d} P(\boldsymbol{z}\bar{\boldsymbol{w}})f(\boldsymbol{w})\,\boldsymbol{m}(\mathrm{d}\boldsymbol{w}),\quad \forall \boldsymbol{z} \in \mathbb{T}^d
	\]
	is a $C^k$-function and for any multi-index $\boldsymbol{\alpha}$ with $|\boldsymbol{\alpha}|\le k$, we have
	\begin{equation}\label{eq:diff-convolution}
	D^{\boldsymbol{\alpha}}(P*f)(\boldsymbol{z})=((D^{\boldsymbol{\alpha}} P)*f)(\boldsymbol{z}),\quad \forall \boldsymbol{z}\in \mathbb{T}^d.
	\end{equation}

