\label{lemma:pou-scaling-Td}
	Let $d\ge 1$ be an integer. There exists a sequence of $C^\infty(\mathbb{T}^d)$-functions $\{\varphi_k\}_{k\in \mathbb{N}\setminus\{0\}}$ such that for any $k\ge 1$, the following properties hold:  
	\begin{itemize}
		\item[(1)] The translations of $\varphi_k$ form a partition of unity on $\mathbb{T}^d$, that is,
		\begin{equation}\label{eq:pou-Td-euclidean-coordinate}
			\sum_{\boldsymbol{I}\in \mathscr{D}_k} \varphi_{k}(\mathcal{E}(\boldsymbol{t}-\boldsymbol{c_I}))=1,\quad \forall \boldsymbol{t}\in [-1/2,1/2)^d.
		\end{equation}
		\item[(2)] The support of $\varphi_k$ is contained in $\mathcal{E}([-2^{-k},2^{k}]^d)\coloneq \{\mathcal{E}(\boldsymbol{t}):\boldsymbol{t}\in [-2^{-k},2^{k}]^d \}$.
		\item[(3)] For each $\boldsymbol{\alpha}\in \mathbb{N}^d$, the derivatives of $\varphi_k$ satisfy the scaling property
		\[
		\|D^{\boldsymbol{\alpha}} \varphi_k\|_{L^\infty(\mathbb{T}^d)}\le C(|\boldsymbol{\alpha}|) 2^{k|\boldsymbol{\alpha}|},
		\]
		where the constant $C(|\boldsymbol{\alpha}|)$ is independent of $k$.
	\end{itemize}

\label{prop:smooth-decomposition-log-correlated-field}
There exists a sequence of independent, stationary, centered Gaussian processes, denoted by $(\psi_j(\boldsymbol{z}))_{\boldsymbol{z} \in \mathbb{T}^d}$ for each $j\in \mathbb{N}\setminus\{0\}$, whose associated covariance kernels $\mathcal{K}_j$ and functions $K_j$ (as defined above) satisfy the following properties:
\begin{enumerate}
    \item[(P0)] (Smoothness). The sample paths of all the Gaussian processes $(\psi_j(\boldsymbol{z}))_{\boldsymbol{z}\in \mathbb{T}^d}$ belong to $C^\infty(\mathbb{T}^d)$ almost surely.

    \item[(P1)] (Finite dependence). If $d_{\mathbb{T}^d}(\boldsymbol{z}, \boldsymbol{w}) \ge 3 \cdot 2^{-j}$, then the kernel $K_j(\boldsymbol{z}, \boldsymbol{w}) = 0$.

    \item[(P2)] (Sum to log-correlation). The sum of the covariance kernels is of logarithmic type:
    \[
    \sum_{j=1}^{\infty} K_j(\boldsymbol{z}, \boldsymbol{w}) = \log_+ \frac{1}{d_{\mathbb{T}^d}(\boldsymbol{z}, \boldsymbol{w})} + g(\boldsymbol{z}\bar{\boldsymbol{w}}),    \quad \text{with $g \in C(\mathbb{T}^d)$.}
    \]



    \item[(P3)] (Limiting variance).  The variances of the processes, given by $\mathcal{K}_j(\mathbf{1})$, have the limit:
    \[
    \lim_{j \to \infty} \mathcal{K}_j(\boldsymbol{1}) =\lim\limits_{j\to \infty}\mathbb{E}[\psi_j(\boldsymbol{t})^2]=\log 2.
    \]

    \item[(P4)] (Uniform Derivative Bounds). There exists an increasing function $\Theta: (0, \infty) \to [1, \infty)$ such that for all $p > 0$,
    \begin{align}\label{incr-p-moment}
        \sup_{j} \sup_{|\boldsymbol{\alpha}| \le d} \sup_{\boldsymbol{z}\in \mathbb{T}^d} \frac{\mathbb{E}[|D^{\boldsymbol{\alpha}}\psi_j(\boldsymbol{z})|^p]}{j^{2|\boldsymbol{\alpha}|p}2^{j|\boldsymbol{\alpha}|p}} \le \Theta(p).
    \end{align}
\end{enumerate}

\label{lemma:properties-Hj}
	The positive definite function $\mathcal{H}_j$ satisfies the following properties:
\begin{itemize}
	\item[(1)] For all $\boldsymbol{z}\in \mathbb{T}^d$, $\mathcal{H}_j(\boldsymbol{z})=\mathcal{H}_j(\bar{\boldsymbol{z}})$.
    \item[(2)] The support of $\mathcal{H}_j$ is contained in $\overline{B}(\boldsymbol{1},2^{-j})$.
    \item[(3)] The sum of $\mathcal{H}_j$ is of log-type, that is,
    \[
	\sum_{j=1}^\infty \mathcal{H}_j(\boldsymbol{z})=\log_+\frac{1}{\|\boldsymbol{z}\|}+g_0(\|\boldsymbol{z}\|),\quad \forall \boldsymbol{z}\in \mathbb{T}^d\setminus\{\boldsymbol{1}\}.
	\]
\end{itemize}

